import { NextResponse } from 'next/server'
import { redis } from '@/lib/redis'

export const runtime = 'edge'

const HEURISTIC_MIN = 122
const HEURISTIC_MAX = 192
const HEURISTIC_TTL = 35 // seconds — slightly longer than client poll interval

// GET /api/active-users
// Returns: { count: number }
// Count = heuristic baseline (122-192) + real users from heartbeat in last 60s
export async function GET() {
  try {
    // 1. Heuristic baseline — refresh if expired
    let base = await redis.get<number>('active:heuristic-base')
    if (base === null) {
      base = Math.floor(Math.random() * (HEURISTIC_MAX - HEURISTIC_MIN + 1)) + HEURISTIC_MIN
      await redis.set('active:heuristic-base', base, { ex: HEURISTIC_TTL })
    }

    // 2. Real active users in last 60s
    const cutoff = Date.now() - 60_000
    const real = await redis.zcount('active:users', cutoff, '+inf')

    return NextResponse.json({ count: Number(base) + real })
  } catch {
    // Fallback: pure heuristic
    return NextResponse.json({ count: Math.floor(Math.random() * 71) + 122 })
  }
}

import { NextResponse } from 'next/server'
import { redis } from '@/lib/redis'
import { VOTE_LUA } from '@/lib/vote'
import { getLiveMatches } from '@/lib/matches'

export const runtime = 'edge'

const VOTE_TTL = 3 * 60 * 60 // 3 hours (match + buffer)

function getClientIp(req: Request): string {
  return (
    req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
    req.headers.get('cf-connecting-ip') ||
    'unknown'
  )
}

// POST /api/vote — cast a vote
// Body: { matchId: string, channelId: string }
// Returns: { ok, alreadyVoted?, votedFor? }
export async function POST(req: Request) {
  try {
    const { matchId, channelId } = await req.json()
    if (!matchId || !channelId) {
      return NextResponse.json({ error: 'matchId and channelId required' }, { status: 400 })
    }

    // Verify match is live right now
    const liveMatches = getLiveMatches()
    if (!liveMatches.find(m => m.id === matchId)) {
      return NextResponse.json({ error: 'Match is not currently live' }, { status: 400 })
    }

    const ip = getClientIp(req)
    const voteKey = `vote:${matchId}:${ip}`
    const tallyKey = `votes:match:${matchId}`

    const result: [number, string] = await redis.eval(
      VOTE_LUA,
      [voteKey, tallyKey],
      [channelId, String(VOTE_TTL)],
    )

    const [isNew, channel] = result
    if (isNew === 0) {
      return NextResponse.json({ ok: false, alreadyVoted: true, votedFor: channel })
    }

    return NextResponse.json({ ok: true, alreadyVoted: false })
  } catch (err: any) {
    return NextResponse.json({ error: err.message || 'Vote failed' }, { status: 500 })
  }
}

// GET /api/vote?match={matchId} — get vote counts
export async function GET(req: Request) {
  try {
    const matchId = new URL(req.url).searchParams.get('match')
    if (!matchId) {
      return NextResponse.json({ error: 'match query param required' }, { status: 400 })
    }

    const tallyKey = `votes:match:${matchId}`
    const counts: Record<string, string> | null = await redis.hgetall(tallyKey)
    const entries = Object.entries(counts || {}).map(([channelId, count]) => ({
      channelId,
      votes: Number(count),
    }))
    entries.sort((a, b) => b.votes - a.votes)

    return NextResponse.json({ matchId, channels: entries, total: entries.reduce((s, e) => s + e.votes, 0) })
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 })
  }
}

