import { NextResponse } from 'next/server'

export const runtime = 'edge'

// Only check World Cup channels — curated list is small enough to check every time.
export async function GET(req: Request) {
  const secret = req.headers.get('x-cron-secret')
  if (secret !== process.env.CRON_SECRET) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    const wcResult = await db.query('SELECT id, stream_url FROM channels WHERE is_worldcup = true')
    const wcChannels = wcResult.rows

    await Promise.all(wcChannels.map(async (ch) => {
      const live = await verifyStream(ch.stream_url)
      await redis.set(`health:${ch.id}`, live ? 'live' : 'dead', { ex: 3600 })
      await db.query('UPDATE channels SET is_live = $1, last_checked = now() WHERE id = $2', [live, ch.id])
    }))

    return NextResponse.json({ ok: true, checked: wcChannels.length })
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 })
  }
}

