export const runtime = 'edge'

const HEARTBEAT_WINDOW_MS = 60_000 // count users active within last 60s

// POST /api/heartbeat — record user presence
export async function POST(req: Request) {
  try {
    const ip =
      req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
      req.headers.get('cf-connecting-ip') ||
      'unknown'

    const now = Date.now()
    await redis.zadd('active:users', { score: now, member: ip })
    // Trim entries older than 2 minutes to keep set small
    await redis.zremrangebyscore('active:users', 0, now - HEARTBEAT_WINDOW_MS * 2)

    return NextResponse.json({ ok: true })
  } catch {
    return NextResponse.json({ ok: true }) // silent fail — non-critical
  }
}

import { NextRequest } from 'next/server'

export const runtime = 'edge'
export const dynamic = 'force-dynamic'

// HLS relay proxy — rewrites manifests and streams segments via our origin.
// Mitigates CORS and prevents SSRF by only allowing http/https URLs.

const PROXY_TIMEOUT_MS = 15000

export async function GET(req: NextRequest) {
  const target = req.nextUrl.searchParams.get('url')
  if (!target) return new Response('Missing url param', { status: 400 })

  // Basic SSRF guard — only allow http/https
  let parsed: URL
  try {
    parsed = new URL(target)
  } catch {
    return new Response('Invalid URL', { status: 400 })
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    return new Response('Only http/https URLs are allowed', { status: 400 })
  }

  let upstream: Response
  try {
    upstream = await fetch(target, {
      signal: AbortSignal.timeout(PROXY_TIMEOUT_MS),
      headers: {
        'User-Agent': 'Mozilla/5.0',
        'Referer': parsed.origin + '/',
      },
    })
  } catch (err: any) {
    const msg = err?.name === 'TimeoutError' ? 'Upstream timed out' : 'Upstream fetch failed'
    return new Response(msg, { status: 502 })
  }

  const contentType = upstream.headers.get('content-type') || ''
  const isManifest =
    /mpegurl|m3u8/i.test(contentType) || target.split('?')[0].endsWith('.m3u8')

  const proxyPath = req.nextUrl.pathname
  const wrap = (raw: string) => {
    try {
      const abs = new URL(raw, target).toString()
      return `${proxyPath}?url=${encodeURIComponent(abs)}`
    } catch {
      return raw
    }
  }

  if (isManifest) {
    const text = await upstream.text()
    const rewritten = text
      .split('\n')
      .map((line) => {
        const t = line.trim()
        if (!t) return line
        if (t.startsWith('#')) {
          return line.replace(/URI="([^"]+)"/g, (_m, uri) => `URI="${wrap(uri)}"`)
        }
        return wrap(t)
      })
      .join('\n')

    return new Response(rewritten, {
      status: upstream.status,
      headers: {
        'Content-Type': 'application/vnd.apple.mpegurl',
        'Access-Control-Allow-Origin': '*',
        'Cache-Control': 'no-cache',
      },
    })
  }

  const headers = new Headers()
  const ct = upstream.headers.get('content-type')
  if (ct) headers.set('Content-Type', ct)
  headers.set('Access-Control-Allow-Origin', '*')
  headers.set('Cache-Control', 'public, max-age=5')
  return new Response(upstream.body, { status: upstream.status, headers })
}

