import { NextResponse } from 'next/server'
import { db } from '@/lib/db'

export const runtime = 'edge'

const AUTH_HEADER = 'x-api-key'

function isAuthorized(req: Request): boolean {
  const secret = req.headers.get(AUTH_HEADER) || req.headers.get('x-cron-secret')
  return secret === process.env.CRON_SECRET
}

const SUPPORTED_CATEGORIES = [
  'movies', 'news', 'entertainment', 'music', 'documentary',
  'kids', 'science', 'general', 'sports', 'business', 'education',
  'culture', 'lifestyle', 'travel', 'religious', 'comedy',
  'anime', 'series', 'shop', 'outdoor', 'legislative',
]

interface ParsedChannel {
  tvg_id: string
  name: string
  logo_url: string
  stream_url: string
  category: string
  country_code: string
  language: string
}

function parseM3U(m3uText: string): ParsedChannel[] {
  const lines = m3uText.split('\n')
  const channels: ParsedChannel[] = []
  let current: Partial<ParsedChannel> = {}

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (!line) continue

    if (line.startsWith('#EXTINF:')) {
      const tvgIdMatch = line.match(/tvg-id="([^"]*)"/)
      const logoMatch = line.match(/tvg-logo="([^"]*)"/)
      const groupMatch = line.match(/group-title="([^"]*)"/)
      const countryMatch = line.match(/tvg-country="([^"]*)"/)
      const langMatch = line.match(/tvg-language="([^"]*)"/)

      const commaSplit = line.split(',')
      const name = commaSplit.length > 1 ? commaSplit[commaSplit.length - 1].trim() : 'Unknown'

      current = {
        tvg_id: tvgIdMatch?.[1] || '',
        name,
        logo_url: logoMatch?.[1] || '',
        category: groupMatch?.[1] || '',
        country_code: countryMatch?.[1] || '',
        language: langMatch?.[1] || '',
        stream_url: '',
      }
    } else if (!line.startsWith('#') && current.name) {
      current.stream_url = line
      channels.push({
        tvg_id: current.tvg_id! || current.name.toLowerCase().replace(/[^a-z0-9]/g, ''),
        name: current.name,
        logo_url: current.logo_url || '',
        category: current.category || 'General',
        country_code: current.country_code || '',
        language: current.language || '',
        stream_url: line,
      })
      current = {}
    }
  }
  return channels
}

function chunk<T>(arr: T[], size: number): T[][] {
  return Array.from({ length: Math.ceil(arr.length / size) }, (_, i) =>
    arr.slice(i * size, i * size + size)
  )
}

export async function GET(req: Request) {
  if (!isAuthorized(req)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { searchParams } = new URL(req.url)
  const category = searchParams.get('category')?.toLowerCase()
  const country = searchParams.get('country')?.toLowerCase()
  const limit = Math.min(Number(searchParams.get('limit')) || 200, 1000)

  if (!category && !country) {
    return NextResponse.json({ error: 'Must provide category or country' }, { status: 400 })
  }

  const url = country 
    ? `https://iptv-org.github.io/iptv/countries/${country}.m3u`
    : `https://iptv-org.github.io/iptv/categories/${category}.m3u`

  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(30000) })
    if (!res.ok) return NextResponse.json({ error: `Failed to fetch: ${res.status}` }, { status: 502 })

    const text = await res.text()
    const allChannels = parseM3U(text)
    const channels = allChannels.slice(0, limit)

    // Deduplicate by tvg_id
    const unique = Array.from(new Map(channels.map(c => [c.tvg_id, c])).values())

    let inserted = 0
    for (const batch of chunk(unique, 200)) {
      let paramIndex = 1
      const values: any[] = []
      const placeholders = batch.map(c => {
        const p = `($${paramIndex++}, $${paramIndex++}, $${paramIndex++}, $${paramIndex++}, $${paramIndex++}, $${paramIndex++}, $${paramIndex++})`
        const cat = c.category || category || 'General'
        const cCode = c.country_code || country || ''
        values.push(c.tvg_id, c.name, c.logo_url, c.stream_url, cat, cCode, false)
        return p
      }).join(',')

      const result = await db.query(`
        INSERT INTO channels (tvg_id, name, logo_url, stream_url, category, country_code, is_worldcup)
        VALUES ${placeholders}
        ON CONFLICT (tvg_id) DO UPDATE SET
          stream_url = EXCLUDED.stream_url,
          logo_url   = EXCLUDED.logo_url,
          category   = EXCLUDED.category,
          updated_at = now()
        RETURNING id
      `, values)
      inserted += result.rows.length
    }

    // Flush cache
    const { redis } = await import('@/lib/redis')
    await redis.del('channels:nonwc:all')

    return NextResponse.json({
      ok: true,
      category,
      country,
      total: allChannels.length,
      imported: unique.length,
      inserted,
    })
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { db } from '@/lib/db'

export const runtime = 'edge'

export async function GET(req: Request) {
  try {
    const { searchParams } = new URL(req.url)
    const worldcup = searchParams.get('worldcup')
    const category = searchParams.get('category')

    let query: string
    let params: any[] = []
    let cacheKey: string

    if (worldcup && worldcup !== 'all') {
      cacheKey = `channels:wc:${worldcup}`
      query = `SELECT * FROM channels WHERE is_worldcup = true AND wc_lang = $1 ORDER BY name`
      params = [worldcup]
    } else if (worldcup === 'all') {
      cacheKey = `channels:wc:all`
      query = `SELECT * FROM channels WHERE is_worldcup = true ORDER BY wc_lang, name`
      params = []
    } else if (category) {
      cacheKey = `channels:cat:${category}`
      query = `SELECT * FROM channels WHERE is_worldcup = false AND category = $1 ORDER BY name`
      params = [category]
    } else {
      cacheKey = `channels:nonwc:all`
      query = `SELECT * FROM channels WHERE is_worldcup = false ORDER BY category, name`
      params = []
    }

    let cached = null
    try {
      const { redis } = await import('@/lib/redis')
      if (process.env.UPSTASH_REDIS_REST_URL) {
        cached = await redis.get(cacheKey)
      }
    } catch (e) {
      console.warn('Redis GET failed:', e)
    }

    if (cached) {
      return NextResponse.json(typeof cached === 'string' ? JSON.parse(cached) : cached)
    }

    const result = await db.query(query, params)

    try {
      const { redis } = await import('@/lib/redis')
      if (process.env.UPSTASH_REDIS_REST_URL) {
        await redis.set(cacheKey, JSON.stringify(result.rows), { ex: 21600 })
      }
    } catch (e) {
      console.warn('Redis SET failed:', e)
    }

    return NextResponse.json(result.rows)
  } catch (err: any) {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

