import { db } from '@/lib/db'
import { redis } from '@/lib/redis'
import { verifyStream } from '@/lib/health'
import { NextResponse } from 'next/server'

export const runtime = 'edge'

export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params


  try {
    const result = await db.query('SELECT * FROM channels WHERE id = $1', [id])
    const channel = result.rows[0]

    if (!channel) {
      return NextResponse.json({ error: 'Channel not found' }, { status: 404 })
    }

    // Check Redis health cache first
    const cached = await redis.get(`health:${id}`)
    if (cached) {
      return NextResponse.json({ ...channel, is_live: cached === 'live' })
    }

    // Verify live right now
    const live = await verifyStream(channel.stream_url)

    // Cache result for 1 hour (popular) or 24 hours (normal)
    const ttl = channel.is_popular ? 3600 : 86400
    await redis.set(`health:${id}`, live ? 'live' : 'dead', { ex: ttl })

    // Update DB if status changed
    if (live !== channel.is_live) {
      await db.query('UPDATE channels SET is_live = $1 WHERE id = $2', [live, id])
    }

    return NextResponse.json({ ...channel, is_live: live })
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 })
  }
}

