-- FIFA World Cup 26 — curated broadcaster channels only.
-- This replaces the old iptv-org general sync.

CREATE TABLE IF NOT EXISTS channels (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tvg_id        TEXT UNIQUE,
  name          TEXT NOT NULL,
  logo_url      TEXT,
  stream_url    TEXT NOT NULL,
  stream_urls   TEXT[],                    -- fallback URLs (optional)
  category      TEXT DEFAULT 'Sports',
  country_code  TEXT,                      -- ISO 3166-1 alpha-2
  is_live       BOOLEAN DEFAULT true,
  is_popular    BOOLEAN DEFAULT false,
  last_checked  TIMESTAMPTZ,
  view_count    BIGINT DEFAULT 0,
  is_worldcup   BOOLEAN DEFAULT true,      -- all channels are WC now
  wc_lang       TEXT,                      -- en|es|de|fr|it|pt
  created_at    TIMESTAMPTZ DEFAULT now(),
  updated_at    TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_channels_wc_lang ON channels(wc_lang);
CREATE INDEX IF NOT EXISTS idx_channels_country ON channels(country_code);
CREATE INDEX IF NOT EXISTS idx_channels_live ON channels(is_live);
CREATE INDEX IF NOT EXISTS idx_channels_category ON channels(category);
CREATE INDEX IF NOT EXISTS idx_channels_worldcup ON channels(is_worldcup);
CREATE INDEX IF NOT EXISTS idx_channels_worldcup_lang_name ON channels(is_worldcup, wc_lang, name);

